// SUBCLASSING: behavior fixed at compile time; combinations explode
class Coffee { double cost(){ return 2.0; } }
class MilkCoffee extends Coffee { double cost(){ return super.cost() + 0.5; } }
class MilkSugarCoffee extends MilkCoffee { double cost(){ return super.cost() + 0.2; } }
// Every new combo (soy? caramel?) needs yet another subclass.

// DECORATOR: behavior added at runtime by wrapping; combos stay linear
interface Bev { double cost(); }
class Plain implements Bev { public double cost(){ return 2.0; } }
class Milk implements Bev {
    private final Bev inner; Milk(Bev b){ this.inner = b; }
    public double cost(){ return inner.cost() + 0.5; }
}
class Sugar implements Bev {
    private final Bev inner; Sugar(Bev b){ this.inner = b; }
    public double cost(){ return inner.cost() + 0.2; }
}
// new Sugar(new Milk(new Plain())) -> compose any combination at runtime.
