import java.util.concurrent.*;
import java.util.*;

interface UserRepository {
    Optional<User> findById(Long id);
    List<User> findAll();
    void save(User user);
    void deleteById(Long id);
}

record User(Long id, String name, String email) {}

class JpaUserRepository implements UserRepository {
    public Optional<User> findById(Long id) {
        // Real database access via JPA
        return Optional.of(new User(id, "John", "john@example.com"));
    }
    public List<User> findAll() { return List.of(); }
    public void save(User user) { /* persist to DB */ }
    public void deleteById(Long id) { /* delete from DB */ }
}

class CachingUserRepository implements UserRepository {
    private final UserRepository wrapped;
    private final Map<Long, User> cache = new ConcurrentHashMap<>();

    CachingUserRepository(UserRepository repository) {
        this.wrapped = repository;
    }

    public Optional<User> findById(Long id) {
        // Check cache first
        if (cache.containsKey(id)) {
            System.out.println("Cache hit for user " + id);
            return Optional.of(cache.get(id));
        }
        // Cache miss: delegate and store
        var user = wrapped.findById(id);
        user.ifPresent(u -> cache.put(id, u));
        return user;
    }

    public List<User> findAll() {
        return wrapped.findAll();  // Direct delegation for bulk queries
    }

    public void save(User user) {
        wrapped.save(user);  // Write to DB first
        cache.put(user.id(), user);  // Update cache after successful save
    }

    public void deleteById(Long id) {
        wrapped.deleteById(id);
        cache.remove(id);  // Invalidate cache entry
    }
}

// Usage in Spring configuration
UserRepository repo = new CachingUserRepository(new JpaUserRepository());

// Component interface: the shared contract
interface PaymentProcessor {
    boolean processPayment(String orderId, double amount);
    void refund(String orderId);
}

// Concrete component: real payment processing
class StripePaymentProcessor implements PaymentProcessor {
    public boolean processPayment(String orderId, double amount) {
        // Real Stripe API call
        return true;
    }
    public void refund(String orderId) { /* Stripe refund */ }
}

// Another concrete component
class PayPalPaymentProcessor implements PaymentProcessor {
    public boolean processPayment(String orderId, double amount) {
        // Real PayPal API call
        return true;
    }
    public void refund(String orderId) { /* PayPal refund */ }
}

// Decorator: works with ANY PaymentProcessor
class LoggingPaymentDecorator implements PaymentProcessor {
    private final PaymentProcessor wrapped;  // Interface type

    LoggingPaymentDecorator(PaymentProcessor processor) {
        this.wrapped = processor;  // Can wrap Stripe, PayPal, or another decorator
    }

    public boolean processPayment(String orderId, double amount) {
        System.out.println("Processing payment for " + orderId);
        var result = wrapped.processPayment(orderId, amount);  // Delegate
        System.out.println("Payment " + (result ? "succeeded" : "failed"));
        return result;
    }

    public void refund(String orderId) {
        System.out.println("Refunding order " + orderId);
        wrapped.refund(orderId);
    }
}

// Usage: decorators work with any implementation
PaymentProcessor stripeWithLogging = new LoggingPaymentDecorator(
    new StripePaymentProcessor()
);
PaymentProcessor paypalWithLogging = new LoggingPaymentDecorator(
    new PayPalPaymentProcessor()
);

// Component interface
interface Notifier {
    void send(String message);
}

// Concrete component
class EmailNotifier implements Notifier {
    public void send(String message) {
        System.out.println("Sending email: " + message);
    }
}

// Base decorator
abstract class NotifierDecorator implements Notifier {
    protected final Notifier wrapped;

    NotifierDecorator(Notifier notifier) {
        this.wrapped = notifier;
    }
}

// Concrete decorators
class EncryptionDecorator extends NotifierDecorator {
    EncryptionDecorator(Notifier notifier) { super(notifier); }

    public void send(String message) {
        var encrypted = "[ENCRYPTED]" + message;  // Add encryption
        wrapped.send(encrypted);
    }
}

class LoggingDecorator extends NotifierDecorator {
    LoggingDecorator(Notifier notifier) { super(notifier); }

    public void send(String message) {
        System.out.println("LOG: Sending message");  // Add logging
        wrapped.send(message);
        System.out.println("LOG: Message sent");
    }
}

// Usage: stack decorators at runtime
var notifier = new LoggingDecorator(
    new EncryptionDecorator(
        new EmailNotifier()
    )
);
notifier.send("Hello World");

import java.io.*;

public class StreamDecoratorDemo {
    public void readFileWithDecorators(String filepath) throws IOException {
        // Base component: reads raw bytes from file
        InputStream fileStream = new FileInputStream(filepath);

        // First decorator: adds buffering for performance
        InputStream bufferedStream = new BufferedInputStream(fileStream);

        // Second decorator: adds typed reading (readInt, readDouble)
        DataInputStream dataStream = new DataInputStream(bufferedStream);

        // Each decorator wraps the previous, adding behavior
        int value = dataStream.readInt();  // Buffered, typed read from file
        dataStream.close();  // Closes entire decorator chain
    }

    public void alternativeChain(String filepath) throws IOException {
        // Common idiom: nest constructors to build decorator stack
        try (var reader = new BufferedReader(
                new InputStreamReader(
                    new FileInputStream(filepath)))) {

            String line = reader.readLine();  // Buffered, character-decoded read
            System.out.println(line);
        }  // try-with-resources closes all layers
    }
}

interface OrderService {
    Order findById(Long id);
    void save(Order order);
}

@Service
class OrderServiceImpl implements OrderService {
    public Order findById(Long id) {
        // Business logic: fetch from database
        return new Order(id, "Laptop", 999.99);
    }

    public void save(Order order) {
        // Business logic: persist to database
    }
}

class LoggingOrderService implements OrderService {
    private final OrderService wrapped;

    LoggingOrderService(OrderService service) {
        this.wrapped = service;
    }

    public Order findById(Long id) {
        System.out.println("LOG: findById(" + id + ") called");  // Add logging
        var start = System.currentTimeMillis();
        var result = wrapped.findById(id);  // Delegate to wrapped
        System.out.println("LOG: findById took " + (System.currentTimeMillis() - start) + "ms");
        return result;
    }

    public void save(Order order) {
        System.out.println("LOG: save(" + order + ") called");
        wrapped.save(order);
    }
}

class CachingOrderService implements OrderService {
    private final OrderService wrapped;
    private final Map<Long, Order> cache = new ConcurrentHashMap<>();

    CachingOrderService(OrderService service) {
        this.wrapped = service;
    }

    public Order findById(Long id) {
        return cache.computeIfAbsent(id, wrapped::findById);  // Cache or delegate
    }

    public void save(Order order) {
        wrapped.save(order);
        cache.put(order.id(), order);  // Update cache after save
    }
}

// Usage: stack decorators
OrderService service = new LoggingOrderService(
    new CachingOrderService(
        new OrderServiceImpl()
    )
);

