// INHERITANCE: 3 optional features -> up to 8 subclasses (2^3)
interface Notifier { void send(String m); }
class Email implements Notifier { public void send(String m){ System.out.println("email " + m); } }
// EncryptedEmail, CompressedEmail, EncryptedCompressedEmail, ... class explosion

// DECORATOR: 3 features -> 4 classes (base + 3), composed at runtime
abstract class NotifierDecorator implements Notifier {
    protected final Notifier inner;
    NotifierDecorator(Notifier n){ this.inner = n; }
}
class Encrypted extends NotifierDecorator {
    Encrypted(Notifier n){ super(n); }
    public void send(String m){ inner.send("[enc]" + m); }
}
class Logged extends NotifierDecorator {
    Logged(Notifier n){ super(n); }
    public void send(String m){ System.out.println("log"); inner.send(m); }
}
// new Logged(new Encrypted(new Email())) - add features without new subclasses.
