// Step 1: Component interface
interface Coffee {
    double cost();
    String description();
}

// Step 2: Concrete component
class SimpleCoffee implements Coffee {
    public double cost() { return 2.0; }
    public String description() { return "Simple coffee"; }
}

// Step 3: Abstract base decorator (handles delegation)
abstract class CoffeeDecorator implements Coffee {
    protected final Coffee wrapped;  // Hold wrapped component

    protected CoffeeDecorator(Coffee coffee) {
        this.wrapped = coffee;
    }

    // Default delegation for all methods
    public double cost() { return wrapped.cost(); }
    public String description() { return wrapped.description(); }
}

// Step 4: Concrete decorators (override only what they enhance)
class MilkDecorator extends CoffeeDecorator {
    MilkDecorator(Coffee coffee) { super(coffee); }

    public double cost() { return wrapped.cost() + 0.5; }  // Add milk cost
    public String description() { return wrapped.description() + ", milk"; }
}

class SugarDecorator extends CoffeeDecorator {
    SugarDecorator(Coffee coffee) { super(coffee); }

    public double cost() { return wrapped.cost() + 0.2; }  // Add sugar cost
    public String description() { return wrapped.description() + ", sugar"; }
}

// Usage: compose at runtime
Coffee coffee = new SugarDecorator(
    new MilkDecorator(
        new SimpleCoffee()
    )
);
System.out.println(coffee.description() + " = $" + coffee.cost());
// Output: Simple coffee, milk, sugar = $2.7
